const std = @import("std");
const types = @import("types.zig");
const caps_mod = @import("caps.zig");

/// A generative limb (§30): a higher-order capability expressed entirely as
/// declarative, content-addressed data. This interpreter is kernel mechanism
/// — like any VM — but the *policy* it executes is generated by an ordinary
/// neuron's write effect, admitted by digest through the skill registry, and
/// attached with no ambient authority. The interpreter proposes decisions;
/// the runtime still validates and commits every effect.
///
/// Spec format (one rule per line, first match wins):
///
///   limb/v1 <name>
///   on <schema-prefix> terminate <result...>
///   on <schema-prefix> wait <predicate>
///   on <schema-prefix> send <to> <schema> <payload...>
///   on <schema-prefix> write <id> <schema> <bytes...>
///   on <schema-prefix> spawn <id> <kind>
///
/// The schema prefix "*" matches any receptor schema. Rule bodies are slices
/// into the admitted package bytes; the interpreter holds no mutable state.
pub const max_rules = 8;

const spec_sources = [_][]const u8{"stimulus"};
const spec_evidence = [_]types.Evidence{.{
    .claim = "an admitted spec rule matched the receptor schema",
    .sources = &spec_sources,
    .method = "declarative spec interpretation",
}};

pub const SpecNeuron = struct {
    spec: []const u8,
    len: usize = 0,
    matches: [max_rules][]const u8 = undefined,
    controls: [max_rules]types.Control = undefined,
    effects: [max_rules]types.Effect = undefined,
    has_effect: [max_rules]bool = undefined,

    /// Parses an admitted package into an attachable neuron. Malformed
    /// packages are rejected here, before attachment (§29/§30 admit step).
    pub fn init(spec: []const u8) !SpecNeuron {
        var neuron: SpecNeuron = .{ .spec = spec };
        var lines = std.mem.splitScalar(u8, spec, '\n');
        const header = lines.next() orelse return error.InvalidSpec;
        if (!std.mem.startsWith(u8, header, "limb/v1")) return error.InvalidSpec;
        while (lines.next()) |line| {
            if (line.len == 0) continue;
            if (neuron.len >= max_rules) return error.InvalidSpec;
            var tokens = std.mem.tokenizeScalar(u8, line, ' ');
            const on = tokens.next() orelse return error.InvalidSpec;
            if (!std.mem.eql(u8, on, "on")) return error.InvalidSpec;
            const match = tokens.next() orelse return error.InvalidSpec;
            const action = tokens.next() orelse return error.InvalidSpec;
            const index = neuron.len;
            neuron.matches[index] = match;
            neuron.has_effect[index] = false;
            if (std.mem.eql(u8, action, "terminate")) {
                const result = rest(&tokens) orelse return error.InvalidSpec;
                neuron.controls[index] = .{ .terminate = result };
            } else if (std.mem.eql(u8, action, "wait")) {
                const predicate = tokens.next() orelse return error.InvalidSpec;
                neuron.controls[index] = .{ .continue_wait = predicate };
            } else if (std.mem.eql(u8, action, "send")) {
                const to = tokens.next() orelse return error.InvalidSpec;
                const schema = tokens.next() orelse return error.InvalidSpec;
                const payload = rest(&tokens) orelse return error.InvalidSpec;
                neuron.effects[index] = .{ .send = .{
                    .to = to,
                    .schema = schema,
                    .payload = payload,
                } };
                neuron.has_effect[index] = true;
                neuron.controls[index] = .{ .terminate = "fired" };
            } else if (std.mem.eql(u8, action, "write")) {
                const id = tokens.next() orelse return error.InvalidSpec;
                const schema = tokens.next() orelse return error.InvalidSpec;
                const bytes = rest(&tokens) orelse return error.InvalidSpec;
                neuron.effects[index] = .{ .write = .{
                    .id = id,
                    .schema = schema,
                    .bytes = bytes,
                } };
                neuron.has_effect[index] = true;
                neuron.controls[index] = .{ .terminate = "fired" };
            } else if (std.mem.eql(u8, action, "spawn")) {
                const id = tokens.next() orelse return error.InvalidSpec;
                const kind = tokens.next() orelse return error.InvalidSpec;
                neuron.effects[index] = .{ .spawn = .{ .id = id, .kind = kind } };
                neuron.has_effect[index] = true;
                neuron.controls[index] = .{ .terminate = "fired" };
            } else {
                return error.InvalidSpec;
            }
            neuron.len += 1;
        }
        if (neuron.len == 0) return error.InvalidSpec;
        return neuron;
    }

    pub fn fire(self: *const SpecNeuron, stimulus: types.Stimulus, _: caps_mod.Caps) !types.Decision {
        for (0..self.len) |index| {
            const match = self.matches[index];
            if (!std.mem.eql(u8, match, "*") and
                !std.mem.startsWith(u8, stimulus.receptor_schema, match)) continue;
            const effects: []const types.Effect = if (self.has_effect[index])
                self.effects[index .. index + 1]
            else
                &.{};
            return .{
                .control = self.controls[index],
                .effects = effects,
                .evidence = &spec_evidence,
            };
        }
        return .{ .control = .{ .terminate = "no-match" }, .evidence = &spec_evidence };
    }
};

fn rest(tokens: *std.mem.TokenIterator(u8, .scalar)) ?[]const u8 {
    const remaining = std.mem.trim(u8, tokens.rest(), " ");
    if (remaining.len == 0) return null;
    return remaining;
}

test "spec parser rejects malformed packages" {
    try std.testing.expectError(error.InvalidSpec, SpecNeuron.init(""));
    try std.testing.expectError(error.InvalidSpec, SpecNeuron.init("limb/v1 only-a-header\n"));
    try std.testing.expectError(error.InvalidSpec, SpecNeuron.init("limb/v1 x\non a vanish now\n"));
    try std.testing.expectError(error.InvalidSpec, SpecNeuron.init("limb/v1 x\non a terminate\n"));
    try std.testing.expectError(error.InvalidSpec, SpecNeuron.init("not-a-limb\non a terminate x\n"));
}

test "spec neuron routes by receptor schema without ambient authority" {
    const spec =
        "limb/v1 router\n" ++
        "on task/failed send channel/retry task/retry requeue\n" ++
        "on * terminate ignored\n";
    var neuron = try SpecNeuron.init(spec);
    const routed = try neuron.fire(.{
        .firing_id = "s-1",
        .receptor_schema = "task/failed",
    }, .{});
    try std.testing.expectEqual(@as(usize, 1), routed.effects.len);
    try std.testing.expectEqualStrings("channel/retry", routed.effects[0].send.to);
    const ignored = try neuron.fire(.{
        .firing_id = "s-2",
        .receptor_schema = "task/ok",
    }, .{});
    try std.testing.expectEqual(@as(usize, 0), ignored.effects.len);
    try std.testing.expectEqualStrings("ignored", ignored.control.terminate);
}
